select

  distinct


from safety_goods_out_process




  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}

select t.vin_no
from safety_goods_out_process p
       left join safety_goods_out_detail_vehicle t on p.id = t.process_id
where p.id = #{flowId}
  and p.out_factory_id in ('150','154','155')
  and p.out_type_name = #{outTypeName}
  and p.examine_dept = #{examineDept}
  and p.out_person_type = '2'
  and t.vin_no is not null
